from typing import Sequence
def ada_moment(a: Sequence[Sequence[int]]) -> int:
    n = len(a)
    if any(len(row) != n for row in a):
        raise ValueError("matrix must be square")
    ones = [1] * n
    degree = [sum(row[j] * ones[j] for j in range(n)) for row in a]
    weighted = [degree[i] * degree[i] for i in range(n)]
    propagated = [sum(a[i][j] * weighted[j] for j in range(n)) for i in range(n)]
    return sum(propagated)

from fractions import Fraction
from typing import Sequence
def elementary_from_power_sums(power_sums: Sequence[int]) -> list[int]:
    """Return e_1,...,e_n from p_1,...,p_n via Newton identities."""
    e = [Fraction(1)]
    for k in range(1, len(power_sums) + 1):
        numerator = sum(((-1) ** (i - 1)) * e[k - i] * power_sums[i - 1]
                        for i in range(1, k + 1))
        e.append(numerator / k)
    if any(x.denominator != 1 for x in e):
        raise ValueError("inputs are not integral degree power sums")
    return [int(x) for x in e[1:]]
if __name__ == "__main__":
    # Degrees 1, 1, 2 have p_1=4, p_2=6, p_3=10.
    print(elementary_from_power_sums([4, 6, 10]))  # [4, 5, 2]

